const state={messages:[],people:[],fileName:''};
const $=s=>document.querySelector(s); const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#chatFile').addEventListener('change', async e=>{const f=e.target.files[0];if(!f)return; state.fileName=f.name; const parsed=parseChat(await f.text()); if(!parsed.length){$('#fileError').textContent='Não reconheci mensagens neste ficheiro. Exporte a conversa como .txt e tente novamente.';return} state.messages=parsed; setupPeople(parsed); $('#intro').classList.add('hidden');$('#mapping').classList.remove('hidden')});
$('#mappingForm').addEventListener('submit',e=>{e.preventDefault();state.people=[...document.querySelectorAll('[data-original]')].map(input=>({original:input.dataset.original,name:input.value.trim()||input.dataset.original})); render();$('#mapping').classList.add('hidden');$('#report').classList.remove('hidden');window.scrollTo({top:0,behavior:'smooth'})});
$('#newFile').addEventListener('click',()=>location.reload()); $('#pdfButton').addEventListener('click',()=>window.print());
function parseChat(text){const rows=[];const re=/^(?:\[)?(\d{1,2})[\/.](\d{1,2})[\/.](\d{2,4}),?\s+(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM|am|pm)?\]?\s*(?:-|–)?\s*(.*)$/;let current=null;for(const line of text.replace(/^\uFEFF/,'').split(/\r?\n/)){const m=line.match(re);if(m){const tail=m[8];const author=tail.match(/^([^:]+):\s([\s\S]*)$/);if(author){let year=+m[3]; if(year<100)year+=2000;let h=+m[4];if(m[7]){if(m[7].toLowerCase()==='pm'&&h<12)h+=12;if(m[7].toLowerCase()==='am'&&h===12)h=0}const date=new Date(year,+m[1]-1,+m[2],h,+m[5],+(m[6]||0));if(!isNaN(date)){current={date,author:author[1].trim(),text:author[2]};rows.push(current);continue}}current=null}else if(current){current.text+='\n'+line}}return rows}
function setupPeople(msgs){const authors=[...new Set(msgs.map(x=>x.author))].sort((a,b)=>a.localeCompare(b));$('#memberFields').innerHTML=authors.map((a,i)=>`<div class="member-row"><label for="p${i}">${esc(a)}</label><input id="p${i}" data-original="${esc(a)}" value="${esc(a==='You'?'':a)}" placeholder="Nome no contacto / nome real" required></div>`).join('')}
function render(){const names=Object.fromEntries(state.people.map(p=>[p.original,p.name]));const msgs=state.messages.map(m=>({...m,name:names[m.author]||m.author}));const P=state.people.map(p=>p.name);const by=fn=>Object.fromEntries(P.map(p=>[p,fn(p)]));const count=by(p=>msgs.filter(m=>m.name===p).length);const average=by(p=>{const a=msgs.filter(m=>m.name===p);return a.length?a.reduce((n,m)=>n+[...m.text].length,0)/a.length:0});const hrs=Array(24).fill(0),week=Array(7).fill(0),days={};msgs.forEach(m=>{hrs[m.date.getHours()]++;week[(m.date.getDay()+6)%7]++;const k=localDay(m.date);days[k]=(days[k]||0)+1});
const made=Object.fromEntries(P.map(p=>[p,0])), received=Object.fromEntries(P.map(p=>[p,0])); const aliases=P.map(p=>({p,key:p.toLocaleLowerCase()})).sort((a,b)=>b.key.length-a.key.length);msgs.forEach(m=>aliases.forEach(a=>{const r=new RegExp(`(^|[^\\p{L}\\p{N}])@${escapeRE(a.key)}(?=$|[^\\p{L}\\p{N}])`,'iu');if(r.test(m.text.toLocaleLowerCase())){made[m.name]++;received[a.p]++}}));
const start=Object.fromEntries(P.map(p=>[p,0])), replies=Object.fromEntries(P.map(p=>[p,[]]));msgs.forEach((m,i)=>{if(i===0 || m.date-msgs[i-1].date>3600000)start[m.name]++; if(i&&m.name!==msgs[i-1].name){const d=m.date-msgs[i-1].date;if(d<=3600000)replies[m.name].push(d)}});const response=by(p=>replies[p].length?replies[p].reduce((a,b)=>a+b,0)/replies[p].length:null);
$('#reportTitle').textContent='Grupo em números';$('#reportMeta').textContent=`${msgs.length.toLocaleString('pt-BR')} mensagens · ${P.length} membros · ${localDay(msgs[0].date)} — ${localDay(msgs.at(-1).date)}`;$('#generatedAt').textContent=new Date().toLocaleString('pt-BR');
const activeDays=Object.keys(days).length;$('#summaryCards').innerHTML=metric('Mensagens',msgs.length.toLocaleString('pt-BR'))+metric('Membros',P.length)+metric('Dias ativos',activeDays)+metric('Período',activeDays?`${Math.ceil((msgs.at(-1).date-msgs[0].date)/86400000)+1} dias`:'—');
barChart('#messagesChart',count,n=>n.toLocaleString('pt-BR'));barChart('#lengthChart',average,n=>`${Math.round(n)} car.`);miniChart('#hourChart',hrs,Array.from({length:24},(_,i)=>i%3===0?`${i}h`:''));miniChart('#weekdayChart',week,['Seg','Ter','Qua','Qui','Sex','Sáb','Dom']);lineChart('#dailyChart',Object.entries(days));dualChart('#mentionsChart',P,made,received,'Feitas','Recebidas');barChart('#startersChart',start,n=>n);barChart('#responseChart',response,n=>n===null?'—':formatDuration(n));}
function metric(l,v){return `<div class="metric"><small>${l}</small><strong>${v}</strong></div>`}function barChart(sel,obj,fmt){const vals=Object.values(obj).map(v=>v??0),max=Math.max(...vals,1);$(sel).innerHTML=Object.entries(obj).sort((a,b)=>(b[1]??-1)-(a[1]??-1)).map(([k,v])=>`<div class="bar-row"><span class="bar-label">${esc(k)}</span><span class="bar-track"><span class="bar-fill" style="width:${((v??0)/max)*100}%"></span></span><span class="bar-value">${fmt(v)}</span></div>`).join('')}function miniChart(sel,vals,labels){const max=Math.max(...vals,1);$(sel).innerHTML=`<div class="mini-bars">${vals.map((v,i)=>`<span class="mini" style="height:${Math.max(v/max*100,v?3:0)}%" data-tip="${labels[i]||i}: ${v}"></span>`).join('')}</div><div class="axis">${labels.map(x=>`<span>${x}</span>`).join('')}</div>`}function dualChart(sel,people,a,b,x,y){const max=Math.max(...people.map(p=>Math.max(a[p],b[p])),1);$(sel).innerHTML=`<p class="legend"><span><i class="dot" style="background:#a9dfc0"></i>${x}</span><span><i class="dot" style="background:#ff9b67"></i>${y}</span></p>`+people.map(p=>`<div class="bar-row"><span class="bar-label">${esc(p)}</span><span><span class="bar-track" style="display:inline-block;width:49%;margin-right:2%"><span class="bar-fill" style="width:${a[p]/max*100}%"></span></span><span class="bar-track" style="display:inline-block;width:49%"><span class="bar-fill" style="width:${b[p]/max*100}%;background:#ff9b67"></span></span></span><span class="bar-value">${a[p]} / ${b[p]}</span></div>`).join('')}function lineChart(sel,entries){const w=800,h=210,p=16,vals=entries.map(x=>x[1]),max=Math.max(...vals,1),min=Math.min(...vals,0);const points=vals.map((v,i)=>`${p+i*(w-2*p)/Math.max(vals.length-1,1)},${h-p-(v-min)*(h-2*p)/Math.max(max-min,1)}`).join(' ');$(sel).innerHTML=`<svg class="line-svg" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none"><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="#cbd2c8"/><polyline points="${points}" fill="none" stroke="#46856a" stroke-width="3" vector-effect="non-scaling-stroke"/>${vals.map((v,i)=>{const [x,y]=points.split(' ')[i].split(',');return `<circle cx="${x}" cy="${y}" r="3" fill="#46856a"><title>${entries[i][0]}: ${v}</title></circle>`}).join('')}</svg><div class="axis"><span>${entries[0]?.[0]||''}</span><span>${entries.at(-1)?.[0]||''}</span></div>`}function localDay(d){return d.toLocaleDateString('pt-BR')}function escapeRE(s){return s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')}function formatDuration(ms){const mins=Math.round(ms/60000);return mins<60?`${mins} min`:`${Math.floor(mins/60)}h ${mins%60}min`}
